export function kahnOrder(graph) {
  const adjacency = readGraph(graph);
  const nodes = [...adjacency.keys()].sort(compareIds);
  const indegree = new Map(nodes.map((node) => [node, 0]));
  for (const node of nodes) {
    for (const target of adjacency.get(node)) {
      indegree.set(target, indegree.get(target) + 1);
    }
  }
  const ready = [];
  for (const node of nodes) {
    if (indegree.get(node) === 0) insertSorted(ready, node);
  }
  const order = [];
  while (ready.length > 0) {
    const node = ready.shift();
    order.push(node);
    for (const target of adjacency.get(node)) {
      const remaining = indegree.get(target) - 1;
      indegree.set(target, remaining);
      if (remaining === 0) insertSorted(ready, target);
    }
  }
  if (order.length !== nodes.length) return { ok: false, cycle: findCycle(graph) };
  return { ok: true, order };
}

